import * as THREE from './vendor/three.module.js';
export function driftStrength(car,handbrake=false){if(car.isAirborne||car.rampId||Math.abs(car.groundPitch||0)>.08||car.speed<5)return 0;const lateral=Math.abs(car.lateralSpeed||0),slip=lateral/Math.max(car.speed,1);return Math.min(.92,Math.max(0,(lateral-1.4)*.18)*(slip>.1?1:0)+(handbrake&&car.speed>6?.4:0));}
/** A bounded pool of two rear-wheel ribbons. One draw call, no per-frame geometry allocation. */
export class TyreMarks{
 constructor(scene,{capacity=3000,life=55}={}){this.capacity=capacity;this.life=life;this.cursor=0;this.segments=0;this.time=0;this.last=[null,null];this.positions=new Float32Array(capacity*18);this.uvs=new Float32Array(capacity*12);this.birth=new Float32Array(capacity*6).fill(-life);this.strength=new Float32Array(capacity*6);const g=this.geometry=new THREE.BufferGeometry();for(const [name,a,size]of [['position',this.positions,3],['uv',this.uvs,2],['markBirth',this.birth,1],['markStrength',this.strength,1]])g.setAttribute(name,new THREE.BufferAttribute(a,size).setUsage(THREE.DynamicDrawUsage));
 const material=new THREE.MeshBasicMaterial({color:0x030403,transparent:true,opacity:.94,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2});this.uniform={value:0};material.onBeforeCompile=s=>{s.uniforms.markTime=this.uniform;s.vertexShader='attribute float markBirth,markStrength;varying float markAge,markOpacity;varying vec2 markUv;uniform float markTime;\n'+s.vertexShader;s.vertexShader=s.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\nmarkAge=markTime-markBirth;markOpacity=markStrength;markUv=uv;');s.fragmentShader='varying float markAge,markOpacity;varying vec2 markUv;\n'+s.fragmentShader;s.fragmentShader=s.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>\ndiffuseColor.a*=max(0.,1.-markAge/${life.toFixed(1)})*markOpacity*smoothstep(0.,.12,markUv.x)*smoothstep(0.,.12,1.-markUv.x)*(.7+.3*step(.23,fract(markUv.x*5.)));`);};
 this.mesh=new THREE.Mesh(g,material);this.mesh.name='drift-tyre-marks';this.mesh.frustumCulled=false;this.mesh.renderOrder=1;scene.add(this.mesh);g.setDrawRange(0,0);}
 breakTrail(){this.last[0]=this.last[1]=null;}
 stamp(wheel,point,intensity,surface){const old=this.last[wheel];if(!old){this.last[wheel]={...point,kind:surface.kind};return;}const dx=point.x-old.x,dz=point.z-old.z,d=Math.hypot(dx,dz);if(d<.12)return;if(d>3||old.kind!==surface.kind||Math.abs(point.y-old.y)>.3){this.last[wheel]={...point,kind:surface.kind};return;}const nx=-dz/d*.105,nz=dx/d*.105,i=this.cursor,base=i*18,uv=i*12,vertices=[[old.x+nx,old.y,old.z+nz],[old.x-nx,old.y,old.z-nz],[point.x+nx,point.y,point.z+nz],[point.x+nx,point.y,point.z+nz],[old.x-nx,old.y,old.z-nz],[point.x-nx,point.y,point.z-nz]];for(let v=0;v<6;v++){this.positions.set(vertices[[0,2,1,3,5,4][v]],base+v*3);this.birth[i*6+v]=this.time;this.strength[i*6+v]=intensity;}this.uvs.set([0,0,0,1,1,0,0,1,1,1,1,0],uv);this.cursor=(i+1)%this.capacity;this.segments=Math.min(this.capacity,this.segments+1);this.geometry.setDrawRange(0,this.segments*6);this.last[wheel]={...point,kind:surface.kind};}
 update(dt,car,wheels,handbrake,surfaceAt){this.time+=dt;this.uniform.value=this.time;const strength=driftStrength(car,handbrake),surface=surfaceAt(car.x,car.z),grass=surface.kind==='grass';if(!strength&&!grass||car.isAirborne||car.rampId||car.speed<1){this.breakTrail();return;}
 wheels.forEach((w,i)=>{const surface=surfaceAt(w.x,w.z);this.stamp(i,{x:w.x,z:w.z,y:surface.height},surface.kind==='grass'?.24:strength,surface);});for(const a of Object.values(this.geometry.attributes))a.needsUpdate=true;
 }
}
